"""Random valid-document generator for differential testing."""
import random
import string

METHODS = ['GET', 'POST', 'PUT', 'HEAD', 'DELETE', 'PATCH', 'OPTIONS', 'a!#$%&\'*+-.^_`|~']
TARGETS = ['/', '/alpha', '/a/b?c=d', '*', '/x%20y', '/~']
HOSTS = ['node.example', 'Node.Example', 'a.b', 'zz']


def ident(used, index):
    while True:
        name = random.choice(string.ascii_uppercase) + ''.join(
            random.choice(string.ascii_letters + string.digits + '_') for _ in range(random.randrange(0, 3)))
        if name not in used and not keywordish(name):
            used.add(name)
            return name


def keywordish(name):
    import keyword
    return keyword.iskeyword(name)


def definition_source(existing, depth=0):
    """Random byte expression over earlier names."""
    roll = random.random()
    if depth > 2 or roll < 0.25:
        kind = random.random()
        if kind < 0.4:
            return 'b"%s"' % random.choice(['x', 'abc', 'GET /a HTTP/1.1\\r\\n\\r\\n', 'A'*4, '', '\\x01\\xff'])
        if kind < 0.7:
            return '"%s"' % random.choice(['ok', 'ünïcode', '', 'q'])
        return '"%s".encode' % 'x' if False else '"%s"' % random.choice(['long' * 3, 'z'])
    if not existing:
        return 'b"ab"'
    name = random.choice(existing)
    if roll < 0.5:
        return '(%s + %s)' % (name, definition_source(existing, depth + 1))
    if roll < 0.7:
        return '%s * %d' % (name, random.randrange(0, 4))
    if roll < 0.8:
        return '%d * %s' % (name, random.randrange(0, 3))
    if roll < 0.9:
        return '(%s)[%s:%s]' % (name, random.choice(['', '0', '1', '2']), random.choice(['', '1', '3', '5']))
    return '(%s)[:]' % name


def payload_template(definitions, allow_expression=True):
    roll = random.random()
    if allow_expression and roll < 0.3 and definitions:
        return '{{ %s }}' % random.choice(definitions)
    if allow_expression and roll < 0.35:
        return '{{%s}}' % ('b"%s"' % ''.join(random.choice('abc/') for _ in range(4)))
    if roll < 0.5:
        return ''.join(random.choice('abcXYZ:/ ') for _ in range(random.randrange(0, 6)))
    if roll < 0.7:
        parts = ['<<random_string>>' if random.random() < .5 else
                 ''.join(random.choice('abcdefgh') for _ in range(random.randrange(0, 4)))
                 for _ in range(random.randrange(1, 4))]
        return ''.join(parts)
    return ''.join(random.choice('abc') for _ in range(random.randrange(0, 5)))


def request_bytes(rng, expect=None, mode='valid'):
    """Build one origin request blob."""
    if expect is None:
        method = random.choice(METHODS).encode()
        target = random.choice(TARGETS).encode()
        host = random.choice(HOSTS).encode()
    else:
        method = expect['method'].encode()
        target = expect['target'].encode()
        host = expect['host'].encode()
    if mode == 'identity-fuzzy':
        host = host.upper() if random.random() < .5 else host.lower()
        if random.random() < .3:
            host = b'other.example'
    lines = [method + b' ' + target + b' HTTP/1.1']
    if random.random() < 0.9:
        lines.append(b'Host: ' + host)
    if random.random() < 0.2:
        lines.append(b'host: ' + host)
    if random.random() < 0.4:
        lines.append(b'X-A : ' + b'value ')
    if random.random() < 0.3:
        lines.append(b'X-B:\tv\tb\v'.replace(b'\v', b''))
    framing = random.choice(['none', 'length', 'chunked'])
    body = bytes(rng.randrange(256) for _ in range(rng.randrange(0, 6)))
    if random.random() < 0.15:
        body = b''
    if framing == 'length':
        values = [str(len(body))]
        if random.random() < 0.3:
            values.append('0' * random.randrange(1, 3) + str(len(body)))
        if random.random() < 0.2 and body:
            values.append(str(len(body)))
        sep = random.choice([',', ', ', ' , ', ',\t'])
        lines.append(b'Content-Length: ' + sep.join(values).encode())
    elif framing == 'chunked':
        lines.append(b'Transfer-Encoding: ' + random.choice([b'chunked', b'Chunked', b' CHUNKED ']))
        lines.append(b'')
        blob = b'\r\n'.join(lines) + b'\r\n'
        chunks = b''
        if body:
            pieces = [body[:len(body) // 2], body[len(body) // 2:]] if random.random() < .5 else [body]
        else:
            pieces = []
        for piece in pieces:
            if piece:
                size = format(len(piece), 'x' if random.random() < .5 else 'X')
                if random.random() < .3:
                    size = '0' * 2 + size
                suffix = b''
                if random.random() < .3:
                    suffix = b';ok=1'
                chunks += size.encode() + suffix + b'\r\n' + piece + b'\r\n'
        if random.random() < 0.3:
            trailers = b'T: v\r\n'
        else:
            trailers = b''
        return blob + chunks + b'0\r\n' + trailers + b'\r\n'
    lines.append(b'')
    blob = b'\r\n'.join(lines) + b'\r\n'
    if framing == 'length':
        blob += body
    return blob


def broken_blob(rng):
    choice = rng.randrange(14)
    return [
        b'GET / HTTP/1.1\n\n',                       # bare LF
        b'GET / HTTP/1.0\r\n\r\n',                   # bad version
        b'GET  / HTTP/1.1\r\n\r\n',                  # empty target
        b'GE T / HTTP/1.1\r\n\r\n',                  # bad method
        b'GET /\r\n\r\n',                            # short request line
        b'GET / HTTP/1.1\r\nBad Header\r\n\r\n',     # no colon
        b'GET / HTTP/1.1\r\nHo st: x\r\n\r\n',       # bad field name
        b'GET / HTTP/1.1\r\nX: \x01\r\n\r\n',        # bad value char
        b'GET / HTTP/1.1\r\nContent-Length: 5, 6\r\n\r\n',
        b'GET / HTTP/1.1\r\nContent-Length:\r\n\r\n',
        b'GET / HTTP/1.1\r\nTransfer-Encoding: gzip\r\n\r\n',
        b'GET / HTTP/1.1\r\nTransfer-Encoding: chunked\r\nContent-Length: 0\r\n\r\n',
        b'GET / HTTP/1.1\r\nTransfer-Encoding: chunked\r\nTransfer-Encoding: chunked\r\n\r\n',
        b'GET / HTTP/1.1\r\n\r\n0\r\nZ\r\n\r\n',
    ][choice]


def document(rng, expects_by_case=None):
    names = []
    for _ in range(rng.randrange(0, 4)):
        name = ''.join(rng.choice(string.ascii_lowercase) for _ in range(4))
        if name not in names:
            names.append(name)
    definitions = []
    defined = []
    for _ in range(rng.randrange(0, 4)):
        name = ident(set(defined), len(defined))
        definitions.append([name, definition_source(defined)])
        defined.append(name)
    cases = []
    used = set()
    for index, name in enumerate(names):
        frames = []
        for _ in range(rng.randrange(0, 4)):
            kind = rng.choice(['headers', 'headers', 'data', 'datagram', 'sleep'])
            if kind == 'sleep':
                frames.append({'Type': 'sleep', 'Time_to_Stop': rng.randrange(0, 12)})
            elif kind == 'headers':
                count = rng.randrange(0, 4)
                rows = [[payload_template(defined), payload_template(defined)]
                        for _ in range(count)]
                if rng.random() < 0.5:
                    frame = {'Type': 'headers',
                             'headers_kv': {row[0]: row[1] for row in rows}}
                else:
                    frame = {'Type': 'headers', 'data_to_transfered': rows}
                if rng.random() < 0.7:
                    frame['End_Stream'] = rng.random() < 0.6
                frames.append(frame)
            else:
                frame = {'Type': kind, 'data_to_transfered': payload_template(defined)}
                if rng.random() < 0.7:
                    frame['End_Stream'] = rng.random() < 0.6
                frames.append(frame)
        method = rng.choice(METHODS)
        target = rng.choice(TARGETS)
        host = rng.choice(HOSTS)
        expect = {'method': method, 'target': target, 'host': host}
        cases.append({'name': name, 'frames': frames, 'expect': expect})
    timeout = rng.randrange(1, 30)
    events = []
    for _ in range(rng.randrange(0, 6)):
        kind = rng.choice(['headers', 'data', 'close'])
        at = rng.randrange(0, 25)
        if kind == 'close':
            events.append({'at': at, 'kind': 'close'})
            continue
        stream = rng.choice([4 * i for i in range(len(cases))] + [99, 4])
        row = {'at': at, 'kind': kind, 'stream': stream, 'end': rng.random() < 0.5}
        if kind == 'headers':
            row['fields'] = [[payload_template(defined), payload_template(defined)]
                             for _ in range(rng.randrange(0, 3))]
        else:
            row['data'] = payload_template(defined)
        events.append(row)
    channels = []
    for cindex in range(rng.randrange(0, 3)):
        parts = []
        for _ in range(rng.randrange(0, 4)):
            owner = rng.choice([None] + names)
            if rng.random() < 0.2:
                blob = broken_blob(rng)
            else:
                expect = None
                if owner is not None and rng.random() < 0.7:
                    for case in cases:
                        if case['name'] == owner:
                            expect = case['expect']
                blob = request_bytes(rng, expect,
                                     'identity-fuzzy' if expect and rng.random() < .4 else 'valid')
            if rng.random() < 0.25 and blob:
                blob = blob[:rng.randrange(0, len(blob))]
            data = blob.decode('latin-1') if all(c < 128 for c in blob) else None
            if data is None:
                # represent arbitrary bytes through a bytes expression template
                data = '{{b"%s"}}' % ''.join('\\x%02x' % c for c in blob)
            parts.append({'case': owner, 'data': data})
        channels.append({'name': ''.join(rng.choice(string.ascii_lowercase) for _ in range(4)),
                         'parts': parts})
    return {'seed': ''.join(rng.choice(string.ascii_letters + '._-') for _ in range(rng.randrange(0, 8))),
            'definitions': definitions, 'timeout_ms': timeout, 'cases': cases,
            'events': events, 'channels': channels}
